===== BusinessDay.java =====
     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import java.time.DayOfWeek;
     4	import java.time.LocalDate;
     5	import java.util.Set;
     6	
     7	/**
     8	 * The registration date must fall on a business day. Computes the EFFECTIVE registration date for a
     9	 * create: the date supplied on the request, or the server's current date when none was supplied,
    10	 * rolled forward to the next business day when it lands on a Saturday, Sunday or public holiday.
    11	 * Every value derived from the registration date (the membership number's year segment, the daily
    12	 * create-limit's day) uses this adjusted date.
    13	 */
    14	public final class BusinessDay {
    15	
    16	    /** Fixed public holidays the business-day roll skips. */
    17	    private static final Set<LocalDate> HOLIDAYS = Set.of(
    18	            LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
    19	            LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
    20	
    21	    private BusinessDay() {
    22	    }
    23	
    24	    /**
    25	     * The effective registration date for a create: {@code supplied} when present, otherwise the
    26	     * server's current date, rolled forward off a weekend to the next Monday.
    27	     */
    28	    public static LocalDate effectiveRegistrationDate(LocalDate supplied) {
    29	        return rollForward(supplied != null ? supplied : LocalDate.now());
    30	    }
    31	
    32	    /**
    33	     * Rolls a Saturday, Sunday or public holiday forward to the next non-holiday business day; a
    34	     * business day that is not a holiday is returned unchanged.
    35	     */
    36	    public static LocalDate rollForward(LocalDate date) {
    37	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
    38	                || HOLIDAYS.contains(date)) {
    39	            date = date.plusDays(1);
    40	        }
    41	        return date;
    42	    }
    43	}
