     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import net.officefloor.plugin.variable.Val;
     4	import org.slf4j.Logger;
     5	import org.slf4j.LoggerFactory;
     6	import org.springframework.samples.petclinic.model.Owner;
     7	
     8	/**
     9	 * Final step of {@code POST /api/owners} that records the successful create on the dedicated
    10	 * {@code AUDIT} logger. Runs after {@link SaveOwner} so the owner's generated {@code id} is
    11	 * available; the line carries the owner id, its {@code customerCode}, its {@code registrationDate},
    12	 * its numeric {@code membershipLevel} and its {@code membershipNumber}.
    13	 */
    14	public class AuditOwnerCreated {
    15	
    16	    private static final Logger audit = LoggerFactory.getLogger("AUDIT");
    17	
    18	    public void service(@Val Owner owner) {
    19	        int points = MembershipPoints.of(owner.getNamesakeCount(), owner.getEmail(),
    20	                owner.getHouseholdSize(), owner.getRegistrationDate());
    21	        audit.info(
    22	                "Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
    23	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
    24	                MembershipLevel.of(points),
    25	                MembershipNumber.of(owner.getCustomerCode(), owner.getRegistrationDate()));
    26	    }
    27	}
