    18	@Mapper(uses = PetMapper.class)
    19	public interface OwnerMapper {
    20	
    21	    @Mapping(target = "salutation",
    22	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.Salutation.of(owner.getTitle(), owner.getLastName()))")
    23	    @Mapping(target = "displayName",
    24	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
    25	    @Mapping(target = "initials",
    26	            expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
    27	    @Mapping(target = "telephoneDisplay",
    28	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.TelephoneDisplay.of(owner.getTelephone()))")
    29	    @Mapping(target = "householdId",
    30	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.Household.id(owner.getLastName(), owner.getPostcode()))")
    31	    @Mapping(target = "identityKey",
    32	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(owner.getTelephone(), owner.getEmail(), owner.getLastName(), owner.getPostcode()))")
    33	    @Mapping(target = "membershipNumber",
    34	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.MembershipNumber.of(owner.getCustomerCode(), owner.getRegistrationDate()))")
    35	    @Mapping(target = "checkDigit",
    36	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.CheckDigit.of(owner.getCustomerCode()))")
    37	    @Mapping(target = "membershipPoints",
