===== MembershipPoints =====
     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import java.time.LocalDate;
     4	import java.time.temporal.ChronoUnit;
     5	
     6	/**
     7	 * Points score behind a pet owner's membership. Every owner starts at 0 points; the score gains 2
     8	 * when the owner has an email address (non-null, non-blank), a further 1 when its
     9	 * {@code namesakeCount} is 0 (no existing owner shares its first and last name), a further 2 when
    10	 * its {@code householdSize} is 3 or more, and a further 3 when more than 365 days have elapsed since
    11	 * the owner's {@code registrationDate}. Because a newly created owner's registration date is the
    12	 * current date, its tenure is zero, so a new owner never earns the tenure points. Derived purely
    13	 * from the owner's own stored state ({@code namesakeCount} and {@code householdSize} are recorded at
    14	 * create time), so it is seed-independent. Used by the owner mapper to expose
    15	 * {@code membershipPoints} on responses and, via {@link MembershipLevel}, {@code membershipLevel}.
    16	 */
    17	public final class MembershipPoints {
    18	
    19	    private MembershipPoints() {
    20	    }
    21	
    22	    /**
    23	     * The membership points for the given namesake count, email, household size and registration
    24	     * date: 0 to start, +2 when the email is present (non-null, non-blank), +1 when the namesake
    25	     * count is exactly 0, +2 when the household size is 3 or more, +3 when the tenure since
    26	     * {@code registrationDate} exceeds 365 days.
    27	     */
    28	    public static int of(Integer namesakeCount, String email, Integer householdSize,
    29	            LocalDate registrationDate) {
    30	        int points = 0;
    31	        boolean hasEmail = email != null && !email.isBlank();
    32	        if (hasEmail) {
    33	            points += 2;
    34	        }
    35	        boolean unique = namesakeCount != null && namesakeCount == 0;
    36	        if (unique) {
    37	            points += 1;
    38	        }
    39	        boolean largeHousehold = householdSize != null && householdSize >= 3;
    40	        if (largeHousehold) {
    41	            points += 2;
    42	        }
    43	        boolean tenured = registrationDate != null
    44	                && ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > 365;
    45	        if (tenured) {
    46	            points += 3;
    47	        }
    48	        return points;
    49	    }
    50	}
===== MembershipLevel =====
     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	/**
     4	 * Numeric membership level for pet owners, from 1 to 4, derived from an owner's
     5	 * {@link MembershipPoints}. The points are banded into a level: 1 for 0-1 points, 2 for 2-3 points,
     6	 * 3 for 4-5 points and 4 for 6 or more points. Because a newly created owner earns no tenure points,
     7	 * a new owner tops out at 5 points (email, unique name and a household of 3 or more), reaching level
     8	 * 4 only once its tenure passes 365 days. Used by the owner mapper to expose {@code membershipLevel}
     9	 * on responses.
    10	 */
    11	public final class MembershipLevel {
    12	
    13	    private MembershipLevel() {
    14	    }
    15	
    16	    /**
    17	     * The membership level for the given points total: 1 for 0-1, 2 for 2-3, 3 for 4-5, 4 for 6 or
    18	     * more.
    19	     */
    20	    public static int of(int points) {
    21	        if (points <= 1) {
    22	            return 1;
    23	        }
    24	        if (points <= 3) {
    25	            return 2;
    26	        }
    27	        if (points <= 5) {
    28	            return 3;
    29	        }
    30	        return 4;
    31	    }
    32	}
