     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import java.time.LocalDate;
     4	import java.time.Period;
     5	
     6	/**
     7	 * Age band for a pet owner, derived from the owner's {@code birthDate} against its
     8	 * {@code registrationDate}: the completed years between the two dates place the owner in
     9	 * {@code MINOR} (under 18), {@code ADULT} (18-64) or {@code SENIOR} (65 or over). Computed against
    10	 * the registration date (the effective, business-day-rolled date stored on the owner) rather than
    11	 * the current date, so the band is stable for the life of the record. Birth date is optional, so an
    12	 * absent birth date (or an absent registration date) yields {@code null} and the field is omitted
    13	 * from responses. Derived purely from the owner's own state, so it carries no stored data and is
    14	 * seed-independent. Used by the owner mapper to expose {@code ageBand} on responses.
    15	 */
    16	public final class AgeBand {
    17	
    18	    private AgeBand() {
    19	    }
    20	
    21	    /**
    22	     * The age band for an owner born on {@code birthDate} as at {@code registrationDate}, or
    23	     * {@code null} when either date is absent.
    24	     */
    25	    public static String of(LocalDate birthDate, LocalDate registrationDate) {
    26	        if (birthDate == null || registrationDate == null) {
    27	            return null;
    28	        }
    29	        int age = Period.between(birthDate, registrationDate).getYears();
    30	        if (age < 18) {
    31	            return "MINOR";
    32	        }
    33	        if (age < 65) {
    34	            return "ADULT";
    35	        }
    36	        return "SENIOR";
    37	    }
    38	}

