            points += 1;
        }
        boolean largeHousehold = householdSize != null && householdSize >= 3;
        if (largeHousehold) {
            points += 2;
        }
        boolean tenured = registrationDate != null
                && ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > 365;
        if (tenured) {
            points += 3;
        }
        return points;
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

/**
 * Points score behind a pet owner's membership. Every owner starts at 0 points; the score gains 2
 * when the owner has an email address (non-null, non-blank), a further 1 when its
 * {@code namesakeCount} is 0 (no existing owner shares its first and last name), a further 2 when
 * its {@code householdSize} is 3 or more, and a further 3 when at least one fiscal year has elapsed
 * since the owner's {@code registrationDate} (the fiscal year starting 1 July — see
 * {@link FiscalYear}), i.e. the owner registered in an earlier fiscal year than the current one.
 * Because a newly created owner's registration date is the current date, it shares the current
 * fiscal year, so a new owner never earns the tenure points. Derived purely from the owner's own
 * stored state ({@code namesakeCount} and {@code householdSize} are recorded at create time), so it
 * is seed-independent. Used by the owner mapper to expose {@code membershipPoints} on responses and,
 * via {@link MembershipLevel}, {@code membershipLevel}.
 */
public final class MembershipPoints {

    private MembershipPoints() {
    }

    /**
     * The membership points for the given namesake count, email, household size and registration
     * date: 0 to start, +2 when the email is present (non-null, non-blank), +1 when the namesake
     * count is exactly 0, +2 when the household size is 3 or more, +3 when at least one fiscal year
     * has elapsed since {@code registrationDate}.
     */
    public static int of(Integer namesakeCount, String email, Integer householdSize,
            LocalDate registrationDate) {
        int points = 0;
        boolean hasEmail = email != null && !email.isBlank();
        if (hasEmail) {
            points += 2;
        }
        boolean unique = namesakeCount != null && namesakeCount == 0;
        if (unique) {
            points += 1;
        }
        boolean largeHousehold = householdSize != null && householdSize >= 3;
        if (largeHousehold) {
            points += 2;
        }
        boolean tenured = registrationDate != null
                && ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > 365;
        if (tenured) {
            points += 3;
        }
        return points;
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Numeric membership level for pet owners, from 1 to 4, derived from an owner's
 * {@link MembershipPoints}. The points are banded into a level: 1 for 0-1 points, 2 for 2-3 points,
 * 3 for 4-5 points and 4 for 6 or more points. Because a newly created owner earns no tenure points,
 * a new owner tops out at 5 points (email, unique name and a household of 3 or more), reaching level
 * 4 only once its tenure passes 365 days. Used by the owner mapper to expose {@code membershipLevel}
 * on responses.
 */
public final class MembershipLevel {

    private MembershipLevel() {
    }

    /**
     * The membership level for the given points total: 1 for 0-1, 2 for 2-3, 3 for 4-5, 4 for 6 or
     * more.
     */
    public static int of(int points) {
        if (points <= 1) {
            return 1;
        }
        if (points <= 3) {
            return 2;
        }
        if (points <= 5) {
            return 3;
        }
        return 4;
    }
}

package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;

import java.util.Collection;
import java.util.List;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class)
public interface OwnerMapper {

    @Mapping(target = "salutation",
            expression = "java(org.springframework.samples.petclinic.rest.function.owner.Salutation.of(owner.getTitle(), owner.getLastName()))")
    @Mapping(target = "displayName",
            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
    @Mapping(target = "initials",
            expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
    @Mapping(target = "telephoneDisplay",
            expression = "java(org.springframework.samples.petclinic.rest.function.owner.TelephoneDisplay.of(owner.getTelephone()))")
    @Mapping(target = "householdId",
            expression = "java(org.springframework.samples.petclinic.rest.function.owner.Household.id(owner.getLastName(), owner.getPostcode()))")
    @Mapping(target = "identityKey",
            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(owner.getTelephone(), owner.getEmail(), owner.getLastName(), owner.getPostcode()))")
    @Mapping(target = "membershipNumber",
            expression = "java(org.springframework.samples.petclinic.rest.function.owner.MembershipNumber.of(owner.getCustomerCode(), owner.getRegistrationDate()))")
    @Mapping(target = "checkDigit",
            expression = "java(org.springframework.samples.petclinic.rest.function.owner.CheckDigit.of(owner.getCustomerCode()))")
    @Mapping(target = "membershipPoints",
            expression = "java(org.springframework.samples.petclinic.rest.function.owner.MembershipPoints.of(owner.getNamesakeCount(), owner.getEmail(), owner.getHouseholdSize(), owner.getRegistrationDate()))")
    @Mapping(target = "membershipLevel",
            expression = "java(org.springframework.samples.petclinic.rest.function.owner.MembershipLevel.of(org.springframework.samples.petclinic.rest.function.owner.MembershipPoints.of(owner.getNamesakeCount(), owner.getEmail(), owner.getHouseholdSize(), owner.getRegistrationDate())))")
    @Mapping(target = "locality",
            expression = "java(org.springframework.samples.petclinic.rest.function.owner.Locality.of(owner.getCustomerCode(), owner.getPostcode(), owner.getCity()))")
    @Mapping(target = "timezone",
            expression = "java(org.springframework.samples.petclinic.rest.function.owner.Timezone.of(owner.getCustomerCode(), owner.getPostcode(), owner.getCity()))")
    @Mapping(target = "contactPreference",
            expression = "java(org.springframework.samples.petclinic.rest.function.owner.ContactPreference.of(owner.getEmail()))")
    @Mapping(target = "ageBand",
            expression = "java(org.springframework.samples.petclinic.rest.function.owner.AgeBand.of(owner.getBirthDate(), owner.getRegistrationDate()))")
    OwnerDto toOwnerDto(Owner owner);

    Owner toOwner(OwnerDto ownerDto);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "pets", ignore = true)
    Owner toOwner(OwnerFieldsDto ownerDto);

    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);

    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);

    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
        OwnerPageDto ownerPageDto = new OwnerPageDto();
        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
        ownerPageDto.setPage(ownerPage.getNumber());
        ownerPageDto.setSize(ownerPage.getSize());
        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
        return ownerPageDto;
    }
}

